\subsubsection{The open-loop formulation}
In the open-loop formulation, player $i$ instead chooses a control $\alpha^i \in \cA_{t_0}^{\ol}$, where $\cA_{t_0}^{\ol}$ denotes the set of square-integrable, $\R^d$-valued processes $\alpha = (\alpha_t)_{t \in [t_0,T]}$, progressively measurable with respect to $\bbF$. In the open-loop case, the dynamics are given by 
\begin{equation} \label{oldynamics}
    \d X_t^i = \alpha^i_t \,\d t + \sqrt{2\sigma} \,\d W_t^i + \sqrt{2 \sigma_0} \,\d W_t^0\,, \quad t_0\leq t \leq T\,, \qquad X_{t_0}^i = \zeta^i_0\,, 
\end{equation}
with the $\zeta^i_0$'s as above, and the cost to player $i$ is
\begin{equation*}
    J^i_{\OL}(t_0,\bzeta_0, \bm \alpha) \defeq \E\bigg[\int_{t_0}^T \!\Big(L^i\big(X_t^i, \alpha_t^i \big) + F^i(\bX_t) \Big)\,\d t + G^i(\bX_T)  \bigg]\,.
\end{equation*}
where implicitly $\bX$ depends on $\bm \alpha$ through the dynamics \eqref{oldynamics}. An open-loop equilibrium (started from $(t_0,\bzeta_0)$) is a tuple $\bm \alpha = (\alpha^1,\dots,\alpha^N) \in (\cA_{t_0}^{\OL})^N$ such that for each $i = 1,\dots,N$, and each $\beta \in \cA_{t_0}^{\OL}$, 
\begin{equation*}
    J^i_{\ol}(t_0,\bzeta_0, \bm \alpha) \leq J^i_{\ol}\big(t_0,\bzeta_0, (\bm \alpha^{-i}, \beta) \big)\,.
\end{equation*}
Open-loop Nash equilibria are described by the \emph{Pontryagin system}, a system of forward-backward stochastic differential equations of the form
\begin{equation} \label{pontryagin} \tag{PS}
    \begin{dcases}
        \d X_t^i = - D_p H^i(X_t^i, Y_t^i)\,\d t + \sqrt{2 \sigma}\, \d W_t^i + \sqrt{2 \sigma_0} \,\d W_t^0
        \\
        \d Y_t^i = \bigl( D_x H^i(X_t^i,Y_t^i) - D_{x^i} F^i(\bX_t) \bigr) \,\d t + \sum_{0 \leq j \leq N} Z_t^{i,j}\, \d W_t^j 
       \\[-3pt]
       X_{t_0}^i = \zeta_0^i, \quad Y_{T}^i = D_{x^i} G^i(\bX_T).
    \end{dcases}
\end{equation}
More precisely, if an open-loop equilibrium exists, then it must take the form
\[
\alpha_t^i = - D_p H^i(X_t^i, Y_t^i)
\]

