\begin{lemma} \label{lem.wibound}
    Let Assumption \ref{assump.disp} hold. Let $(w^i,m^i)_{i = 1,\dots,N}$ denote the solution to \eqref{distpde}. Then $\max_{1 \leq i \leq N} \|Dw^i\|_{\infty} $ has a dimension-free bound.
\end{lemma}

\begin{proof}
    For notational simplicity, set 
    \begin{equation*}
        f^i(t,x) \defeq \int_{(\R^d)^{N-1}} F^i(\by^{-i}, x) \prod_{j \neq i} m_t^j(\d y^j)\,, \qquad g^i(x) \defeq \int_{(\R^d)^{N-1}} G^i(\by^{-i}, x) \prod_{j \neq i} m_T^j(\d y^j)\,.
    \end{equation*}
    Under \Cref{assump.disp}, we have that
    \begin{equation} \label{littlefsemiconvex}
       D_{xx} f^i \geq - C_{\bF,\dis} I_{d}\,, \qquad D_{xx} g^i \geq - C_{\bG, \dis} I_{d}\,.
    \end{equation}
    Fix $t_0 \in [0,T]$, $x_0,\hat{x}_0 \in \R^d$, and define $X$ and $\hat{X}$ to be the solutions to 
    \begin{equation*}
        \d X_t = - D_p H^i(X_t, Dw^i(t,X_t)) \,\d t + \sqrt{2 \sigma} \,\d W_t^i\, ,\qquad X_{t_0} = x_0
    \end{equation*}
    and 
    \begin{equation*}
        \d \hat{X}_t = - D_p H^i(\hat{X}_t, Dw^i(t,\hat{X}_t))\,\d t + \sqrt{2 \sigma} \,\d W_t^i\,, \qquad \hat{X}_{t_0} = \hat{x}_0\,.
    \end{equation*}
    Then set
    \begin{equation*}
        Y_t \defeq D w^i(t,X_t)\,, \qquad Z_t^{i} \defeq \sqrt{2\sigma}\, D^2 w^i(t,X_t)\,, \qquad \alpha_t \defeq - D_p H^i(X_t,Y_t)\,,
        \end{equation*}
        and likewise for $\hat{Y}_t$, $\hat{Z}_t$ and $\hat{\alpha}_t$.
          Recall that we have 
    \begin{equation*}
        \d Y_t = -\bigl(D_x H^i(X_t, Y_t) + D_x f^i(X_t) \bigr) \,\d t + Z_t \,\d W_t^i\,, 
    \end{equation*}
    and likewise for $\hat{Y}$ and $\hat{Z}$. Setting 
    \begin{equation*}
        \Delta Y_t \defeq Y_t - \hat{Y}_t\,, \qquad \Delta{Z}_t \defeq Z_t - \hat{Z}_t\,, 
    \end{equation*}
    we compute $\d(\Delta X_t \cdot \Delta Y_t)$, then we integrate from time $t_0$ to $T$, and, using \eqref{littlefsemiconvex} and \Cref{assump.disp}, we find that
    \begin{equation*}
        |D_{x}w^i(t_0,x_0) - D_x w^i(t_0,\hat{x}_0)|^2 = \E\big[ |\Delta Y_{t_0}|^2 \big] \lesssim |x_0 - \hat{x}_0|^2\,,
    \end{equation*}
    with dimension-free implied constant.
    We omit the details because the computation is almost identical to the one that appears in the proof of \Cref{prop.olboundsdisp}. This completes the proof.
\end{proof}

\begin{lemma} \label{lem.wibound.LL}
    Let \Cref{assump.LL} hold. Let $(w^i,m^i)_{i = 1,\dots,N}$ denote the solution to \eqref{distpde}. Then we have 
    \begin{equation*}
        \max_{i = 1,\dots,N} \|Dw^i\|_{\infty} \lesssim \sigma^{-1}\,,
    \end{equation*}
    with dimension-free implied constant.
\end{lemma}

\begin{proof}
    This is a standard vanishing viscosity estimate for the equation satisfied by $w^i$. We omit the proof.
\end{proof}

\begin{lemma} \label{lem.poincaredisp} 
    Let \Cref{assump.disp} hold, and let $\bzeta_0 = (\zeta^1_0,\dots,\zeta^N_0)$ be an $\scrF_{t_0}$-measurable, square integrable random vector taking values in $(\R^d)^N$, with $(\zeta^i_0)_{i = 1,\dots,N}$ independent. Suppose that for each $i$, $\cL(\zeta_0^i)$ satisfies a Poincar\'e inequality with constant $C_{P,0}^i$, and set
    \begin{equation} \label{CP0def}
        C_{P,0} \defeq \max_{1 \leq i \leq N} C_{P,0}^i\,.
    \end{equation}
    Then there is a dimension-free constant $C_P$ such that for each $t > t_0$, $\cL({\bX}_t^{\Dis,t_0,\bzeta_0})$ satisfies a Poincar\'e inequality with constant $C_{P,0} + C_P$, i.e.\ we have
    \begin{equation*}
        \mathrm{Var}\big(g({\bX}_t^{\Dis,t_0,\bzeta_0}) \big) \leq \big(C_{P,0} + C_P\big)\, \E\Bigl[ \bigl|D g({\bX}_t^{\Dis,t_0,\bzeta_0})\bigr|^2 \Bigr]
    \end{equation*}
    for each function Lipschitz function $g \in C^1((\R^d)^N)$. 
\end{lemma}

\begin{proof}
By a simple extension of \cite[Theorem 1.8]{cattiaux-guillin} (see also \cite[Lemma~4.13]{JacksonLacker}),\footnote{Note that \cite{JacksonLacker} requires $g$ to be Lipschitz and bounded, but using the integrability of $\bX_t^{\Dis,t_0,\bzeta_0}$ there is no issue extending to Lipschitz $g$ via a truncation procedure.} there is a dimension-free constant $C$ such that $m_t^i \defeq \cL({\bX}_t^{\Dis,t_0,\bzeta_0})$ satisfies a Poincar\'e inequality with constant $C_{P,0} + C e^{C \lip(w^i)}$,
where $\lip(w^i)$ indicates the Lipschitz constant of $w^i$. By \Cref{lem.wibound}, $\lip(w^i)$ is dimension-free. 
\end{proof}



\begin{lemma} \label{lem.poincareLL}
    Let \Cref{assump.LL} hold, and let $\bzeta_0$ and be as in \Cref{lem.poincaredisp}. Suppose that for each $i$, $\cL(\zeta_0^i)$ satisfies a Poincar\'e inequality with constant $C_{P,0}^i$, and define $C_{P,0}$ as in \eqref{CP0def}.
    Then there is a dimension-free constant $C_P$ such that for each $t > t_0$, $\cL({\bX}_t^{\Dis,t_0,\bzeta_0})$ satisfies a Poincar\'e inequality with constant $C_{P,0} + e^{c_P(1+\sigma^{-1})}$; i.e.\ we have 
    \begin{equation*}
        \mathrm{Var}\big(g({\bX}_t^{\Dis,t_0,\bzeta_0}) \big) \leq \bigl(C_{P,0} + e^{c_P(1+\sigma^{-1})} \bigr)\E\Bigl[ \bigl|D g({\bX}_t^{\Dis,t_0,\bzeta_0})\bigr|^2 \Bigr]
    \end{equation*}
    for each Lipschitz function $g \in C^1((\R^d)^N)$. 
\end{lemma}

\begin{proof}
    Argue as in the proof of \Cref{lem.poincaredisp}, but invoke \Cref{lem.wibound.LL} in place of \Cref{lem.wibound}.
\end{proof}

We can now prove \Cref{thm.oldistdisp,thm.oldistLL}.

\begin{proof}[Proof of \Cref{thm.oldistdisp}]
Set $\ov{\bX} = {\bX}^{\Dis,t_0,\bzeta_0}$, $\wt{\bX} = {\bX}^{\OL,t_0,\bzeta_0}$. Then we can find $\ov{\bY}$, $\ov{\bZ}$ such that the triple $(\ov{\bX}, \ov{\bY}, \ov{\bZ})$ satisfies \eqref{distfbsde}. By adding and subtracting, we see that $(\ov{\bX}, \ov{\bY}, \ov{\bZ})$ satisfies \eqref{disterrorfbsde}, with
\begin{equation*}
    E_t^{F,i} = \E\big[ D_{i} F^i(\ov{\bX}_t) \mid \ov{X}_t^i \big] - D_{i} F^i(\ov{\bX_t})\,, \qquad  E^{G,i} = \E\big[ D_{i} G^i(\ov{\bX}_T) \mid \ov{X}_T^i \big] - D_{i} G^i(\ov{\bX_T})\,.
\end{equation*}
We note that thanks to Lemma \ref{lem.poincaredisp}, we have 
\begin{equation*}
    \E \big[ |E_t^{F,i}|^2 \big] = \E\big[ \mathrm{Var}(D_{i} F^i(\ov{\bX}_t) \mid \ov{X}_t^i) \big] \leq C_P\, \Bigl\|  \sum_{j \neq i} |D_{ji} F^i|^2 \Bigr\|_{\infty} \leq C_P \kappa^i, 
\end{equation*}
and likewise for $E^{G,i}$, so that in particular
\begin{equation*} 
    \E\bigg[ \int_{t_0}^T |\bm E^{F}|^2 + |\bm E^{G}|^2 \bigg] \leq (1+T)C_P \sum_{1 \leq i \leq N} \kappa^i.
\end{equation*}
The result now follows from combining Lemma \ref{lem.lipschitzstability} with Proposition \ref{prop.olboundsdisp}.
\end{proof}

\begin{proof}[Proof of \Cref{thm.oldistLL}]
   The proof is the same as that of \Cref{thm.oldistdisp} above, except that \Cref{lem.poincareLL} takes the place of \Cref{lem.poincaredisp}, and \Cref{prop.olboundslip} takes the place of \Cref{prop.olboundsdisp}.
\end{proof}


\begin{remark} \label{rmk.distcommonnoise}
    When there is common noise, ``distributed" controls would mean $\bbF^0$-adapted random fields of the form $(\alpha_t(x))_{t_0 \leq t \leq T}$, and the PDE \eqref{distdynamics} would be replaced by a stochastic PDE system analogous to the stochastic MFG system which arises in the theory of MFGs with common noise. Some of our analysis would still apply in this case, but it is not clear how to generalize \Cref{lem.poincaredisp,lem.poincareLL}, so we are unable to generalize the bounds in \Cref{thm.oldistdisp,thm.mainll} to the case when there is common noise. This is why we discuss the distributed formulation only when there is no common noise.
\end{remark}


